import { PokeType } from './type-chart';

export interface BaseStats {
  hp: number;
  atk: number;
  def: number;
  spatk: number;
  spdef: number;
  speed: number;
}

export interface SpeciesDef {
  id: number;
  name: string;
  nameZh: string;
  type: PokeType;
  base: BaseStats;
  ability: string;
  defaultMoves: string[];
  /**
   * 官方种族捕获率（第三世代起，3–255；越大越好抓），见 docs/backend-api.md §2 捕捉公式。
   * 捕捉概率 p = min(1, a/255)，a = ((3*maxHP - 2*curHP) * catchRate * ballBonus) / (3*maxHP)。
   */
  catchRate: number;
  spriteUri: string;
  /** false for legendary/mythical species and evolution-only entries (not in the wild table) */
  inWild: boolean;
}

const S = (
  id: number,
  name: string,
  nameZh: string,
  type: PokeType,
  base: BaseStats,
  ability: string,
  defaultMoves: string[],
  catchRate: number,
  inWild = true,
): SpeciesDef => ({
  id,
  name,
  nameZh,
  type,
  base,
  ability,
  defaultMoves,
  catchRate,
  spriteUri: `minio://assets/sprites/${id}.png`,
  inWild,
});

